[starter-test/src/tasks.ts]
export type TaskStatus = "open" | "done";

export type Task = {
  id: number;
  title: string;
  status: TaskStatus;
};

export function createTask(tasks: Task[], title: string): Task[] {
  const nextId =
    tasks.length === 0 ? 1 : Math.max(...tasks.map((t) => t.id)) + 1;

  const task: Task = {
    id: nextId,
    title,
    status: "open",
  };

  return [...tasks, task];
}

export function listTasks(tasks: Task[], status?: TaskStatus): Task[] {
  if (!status) return tasks;
  return tasks.filter((t) => t.status === status);
}

export function markDone(tasks: Task[], id: number): Task[] {
  if (!tasks.some((t) => t.id === id)) {
    throw new Error(`Task with id ${id} does not exist`);
  }
  return tasks.map((t) => (t.id === id ? { ...t, status: "done" } : t));
}

export function deleteTask(tasks: Task[], id: number): Task[] {
  return tasks.filter((t) => t.id !== id);
}


[starter-test/tests/tasks.test.ts]
import { describe, expect, it } from "vitest";
import { createTask, deleteTask, listTasks, markDone } from "../src/tasks.js";

describe("tasks", () => {
  it("creates tasks", () => {
    let tasks = [];
    tasks = createTask(tasks, "A");
    expect(tasks).toHaveLength(1);
    expect(tasks[0].title).toBe("A");
    expect(tasks[0].status).toBe("open");
  });

  it("marks a task done", () => {
    let tasks = [];
    tasks = createTask(tasks, "A");
    tasks = markDone(tasks, 1);
    expect(tasks[0].status).toBe("done");
  });

  it("throws when marking a non-existing task done", () => {
    let tasks = [];
    tasks = createTask(tasks, "A");
    expect(() => markDone(tasks, 999)).toThrow("Task with id 999 does not exist");
  });

  it("filters done tasks", () => {
    let tasks = [];
    tasks = createTask(tasks, "A");
    tasks = createTask(tasks, "B");
    tasks = markDone(tasks, 1);

    const done = listTasks(tasks, "done");
    expect(done).toHaveLength(1);
    expect(done[0].id).toBe(1);
  });

  it("deletes a task", () => {
    let tasks = [];
    tasks = createTask(tasks, "A");
    tasks = createTask(tasks, "B");

    tasks = deleteTask(tasks, 1);

    expect(tasks).toHaveLength(1);
    expect(tasks[0].id).toBe(2);
    expect(tasks[0].title).toBe("B");
  });
});
